public class Main {
    public static void main(String[] args) {
        Wadah<Integer> w = new WadahApa<>();
        w.simpan(10);
        w.simpan(20);
        System.out.println(w.ambil());
    }
}

interface Wadah<T> {
    void simpan(T x);
    T ambil();
}

class WadahApa<T> implements Wadah<T> {
    private T isi;

    public void simpan(T x) {
        isi = x;
    }

    public T ambil() {
        return isi;
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println(terbesar(3, 9, 5) + " " + terbesar("jeruk", "apel", "mangga"));
    }

    static <T extends Comparable<T>> T terbesar(T a, T b, T c) {
        T max = a;
        if (b.compareTo(max) > 0) max = b;
        if (c.compareTo(max) > 0) max = c;
        return max;
    }
}

