import java.util.List;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        cetakSemua(Arrays.asList(1, 2));
        cetakSemua(Arrays.asList("x", "y"));
    }

    static void cetakSemua(List<?> daftar) {
        for (Object o : daftar) {
            System.out.print(o + " ");
        }
        System.out.println();
    }
}

import java.util.List;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        List<Integer> bulat = Arrays.asList(1, 2, 3);
        List<Double> pecahan = Arrays.asList(1.5, 2.5);
        System.out.println(total(bulat) + " " + total(pecahan));
    }

    static double total(List<? extends Number> angka) {
        double t = 0;
        for (Number n : angka) {
            t += n.doubleValue();
        }
        return t;
    }
}

