import java.util.List;
import java.util.ArrayList;
import java.util.Collections;

public class Main {
    public static void main(String[] args) {
        List<Siswa> daftar = new ArrayList<>();
        daftar.add(new Siswa("Rina", 85));
        daftar.add(new Siswa("Dodi", 70));
        daftar.add(new Siswa("Sari", 92));
        Collections.sort(daftar);
        for (Siswa s : daftar) {
            System.out.print(s.nama + " ");
        }
    }
}

class Siswa implements Comparable<Siswa> {
    String nama;
    int nilai;

    Siswa(String nama, int nilai) {
        this.nama = nama;
        this.nilai = nilai;
    }

    public int compareTo(Siswa lain) {
        return this.nilai - lain.nilai;
    }
}
